#!/usr/bin/env python3
"""Reconcile a CSV of payment transactions into a JSON summary."""
import csv
import json
import sys
from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

STATUSES = {"SUCCESS", "FAILED", "PENDING"}
FINAL_STATUSES = {"SUCCESS", "FAILED"}


def parse_ts(raw):
    """Parse an ISO-8601 timestamp. If naive, assume UTC. Return UTC datetime."""
    raw = raw.strip()
    # Handle trailing Z
    if raw.endswith("Z"):
        raw = raw[:-1] + "+00:00"
    dt = datetime.fromisoformat(raw)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)
    return dt


def parse_amount(raw):
    """Clean monetary amount string and convert to Decimal."""
    s = raw.strip()
    # Remove common currency symbols and commas
    for char in ["$", "€", "£", ",", " "]:
        s = s.replace(char, "")
    # If it's empty after cleaning, invalid
    if not s:
        raise ValueError("Empty amount")
    d = Decimal(s)
    if not d.is_finite():
        raise ValueError("Non-finite amount")
    return d


def load_rows(path):
    """Read well-formed rows; malformed rows are skipped. Keep track of file order index."""
    rows = []
    try:
        with open(path, newline="") as f:
            reader = csv.DictReader(f)
            # Check if required columns are present in fieldnames
            if not reader.fieldnames or not all(col in reader.fieldnames for col in ["tx_id", "timestamp", "amount", "status"]):
                return []
            for idx, row in enumerate(reader):
                try:
                    tx_id_raw = row.get("tx_id")
                    ts_raw = row.get("timestamp")
                    amount_raw = row.get("amount")
                    status_raw = row.get("status")

                    if not tx_id_raw or not ts_raw or not amount_raw or not status_raw:
                        continue

                    tx_id = tx_id_raw.strip()
                    if not tx_id:
                        continue

                    status = status_raw.strip().upper()
                    if status not in STATUSES:
                        continue

                    ts = parse_ts(ts_raw)
                    amount = parse_amount(amount_raw)

                    rows.append({
                        "original_index": idx,
                        "tx_id_key": tx_id.lower(),
                        "tx_id": tx_id,
                        "ts": ts,
                        "amount": amount,
                        "status": status,
                    })
                except (KeyError, AttributeError, ValueError, InvalidOperation):
                    continue
    except Exception:
        return []
    return rows


def dedupe(rows):
    """
    Keep one record per tx_id (case-insensitive, whitespace-stripped):
    - Final (SUCCESS, FAILED) beats PENDING.
    - Among same kind, latest timestamp wins.
    - If exact same instant and kind, later row in file wins.
    """
    best = {}
    for r in rows:
        key = r["tx_id_key"]
        if key not in best:
            best[key] = r
        else:
            cur = best[key]
            r_is_final = 1 if r["status"] in FINAL_STATUSES else 0
            cur_is_final = 1 if cur["status"] in FINAL_STATUSES else 0

            if r_is_final > cur_is_final:
                best[key] = r
            elif r_is_final < cur_is_final:
                continue
            else:
                # Same kind (both final or both pending)
                if r["ts"] > cur["ts"]:
                    best[key] = r
                elif r["ts"] < cur["ts"]:
                    continue
                else:
                    # Same instant and same kind, later row in file wins
                    if r["original_index"] >= cur["original_index"]:
                        best[key] = r
    return list(best.values())


def summarize(rows):
    total = Decimal("0.00")
    valid = 0
    failed = 0
    for r in dedupe(rows):
        if r["status"] == "FAILED":
            failed += 1
        elif r["status"] == "SUCCESS":
            valid += 1
            rounded_amount = r["amount"].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            total += rounded_amount
        # PENDING is ignored

    # Ensure total has at most 2 decimal places in JSON representation
    # We can output float or string or formatted decimal. JSON numbers can be floats or Decimal converted.
    # Python json.dumps serializes float. float(total) is standard.
    return {
        "total_valid_amount": float(total),
        "valid_count": valid,
        "failed_count": failed,
    }


def main():
    if len(sys.argv) != 2:
        print("usage: reconcile.py <transactions.csv>", file=sys.stderr)
        sys.exit(2)

    rows = load_rows(sys.argv[1])
    summary = summarize(rows)
    print(json.dumps(summary))


if __name__ == "__main__":
    main()
